    """Yield multiple preprocessed variants of the image for multi-pass OCR."""
    gray = img.convert('L')
    yield 'orig', img
    for thresh, enh in ((180, 3.0), (200, 2.0), (160, 2.5)):
        boosted = ImageEnhance.Contrast(gray).enhance(enh)
        yield f'thr{thresh}_e{enh}', boosted.point(lambda p: 255 if p > thresh else 0)


def ocr_image(img):
    """Run OCR with multiple configurations and preprocessing variants.

    Returns a list of text blocks (one per pass) for downstream merging.
    """
    texts = []
    for _, variant in _preprocess_variants(img):
        for psm in ('--psm 3', '--psm 6'):
            try:
                texts.append(pytesseract.image_to_string(variant, config=psm))
            except Exception:
                pass
    return texts


