    """Find a plausible date from any OCR pass text.

    Prefers lines explicitly labeled with Date; otherwise first valid.
    """
    def gather(text):
        found = []
        for ln in text.splitlines():
            is_date_line = bool(re.search(r'\bdate\b', ln, re.I))
            for m in _NUMERIC_DATE_RE.finditer(ln):
                d, mo, y = int(m.group(1)), int(m.group(2)), _to_full_year(m.group(3))
