    unlabeled = []
    for t in texts:
        for is_lbl, d in gather(t):
            (labeled if is_lbl else unlabeled).append(d)

    # Prefer majority vote from labeled lines, else from unlabeled
    for pool in (labeled, unlabeled):
        if pool:
            counts = {}
            for d in pool:
                counts[d] = counts.get(d, 0) + 1
            best = max(counts.items(), key=lambda kv: (kv[1], -(date_cls.today() - kv[0]).days))
            return best[0]
    return None


