    """Return the last positive numeric value on the line, or None."""
    candidates = []
    for m in AMOUNT_RE.finditer(line):
        v = parse_number(m.group(1))
        if v is not None and v > 0 and '.' in m.group(1):
            candidates.append(v)
    if candidates:
        return candidates[-1]
    # Allow integers only if no decimal numbers present
    ints = [parse_number(m.group(1)) for m in AMOUNT_RE.finditer(line)]
    ints = [v for v in ints if v is not None and v > 0]
    return ints[-1] if ints else None


