    re.compile(r'^\s*(?:gst|tax|sst)\b', re.I),
    re.compile(r'\bgst\s+payable', re.I),
    re.compile(r'\bserv(?:ice)?\s+(?:charge|tax|chg)\b', re.I),
    re.compile(r'\bsvr\s+tax\b', re.I),
