    """Return total amount parsed from the OCR text, or None."""
    raw_lines = [ln for ln in text.splitlines()]

    for tier in PRIORITY_TIERS:
        matches = []
        for i, ln in enumerate(raw_lines):
            # Find first keyword from tier in the line
