            for kw in tier:
                m = re.search(kw, ln, re.I)
                if m:
                    tier_match = m
                    break
            if not tier_match:
                continue

            # Build the label: text from line start up to the amount location.
            # Simple heuristic: take text before the last amount in the line as label.
            label = ln
            amounts = list(AMOUNT_RE.finditer(ln))
            if amounts:
                label = ln[:amounts[-1].start()]
            if is_excluded(label):
                continue

            amt = find_amount_on_line(ln)
            if amt is None:
