    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])
    for row in rows:
        ws.append(row)
    wb.save(OUT_PATH)
    print(f'Saved to {OUT_PATH}')


if __name__ == '__main__':
    main()
